export const CONTRACT='0xdac17f958d2ee523a2206206994597c13d831ec7';
export const TRANSFER='0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef';
export const ZERO='0x'+'0'.repeat(40);
export function address(a){if(typeof a!=='string'||!/^0x[0-9a-fA-F]{40}$/.test(a.trim())||a.trim().toLowerCase()===ZERO)throw Error('Enter a nonzero Ethereum address: 0x followed by 40 hexadecimal characters.');return a.trim().toLowerCase()}
export function amount(units){const u=BigInt(units);if(u<0n)throw Error('Negative token units');return `${u/1000000n}.${String(u%1000000n).padStart(6,'0')}`.replace(/\.?0+$/,'')||'0'}
export function decode(l){if(l.removed||l.address?.toLowerCase()!==CONTRACT||l.topics?.length!==3||l.topics[0].toLowerCase()!==TRANSFER)throw Error('Unexpected or removed USDT event');if(!l.topics.slice(1).every(t=>/^0x0{24}[0-9a-fA-F]{40}$/.test(t))||!/^0x[0-9a-fA-F]{64}$/.test(l.data))throw Error('Malformed event encoding');for(const k of ['transactionHash','blockHash'])if(!/^0x[0-9a-fA-F]{64}$/.test(l[k]))throw Error('Malformed event hash');for(const k of ['blockNumber','transactionIndex','logIndex'])if(!/^0x[0-9a-fA-F]+$/.test(l[k])||!Number.isSafeInteger(Number(l[k])))throw Error('Malformed event position');return {id:l.transactionHash+':'+Number(l.logIndex),tx:l.transactionHash,block:Number(l.blockNumber),block_hash:l.blockHash,tx_index:Number(l.transactionIndex),log_index:Number(l.logIndex),source:'0x'+l.topics[1].slice(-40).toLowerCase(),target:'0x'+l.topics[2].slice(-40).toLowerCase(),units:BigInt(l.data).toString(),amount:amount(l.data)}}
export const order=(a,b)=>a.block-b.block||a.tx_index-b.tx_index||a.log_index-b.log_index;
export function unique(events){const m=new Map;for(const e of events){const old=m.get(e.id);if(old&&JSON.stringify(old)!==JSON.stringify(e))throw Error('Conflicting duplicate evidence');m.set(e.id,e)}return [...m.values()].sort(order)}
export function findings(events,seed){const incoming=events.filter(e=>e.target===seed&&e.source!==seed),outgoing=events.filter(e=>e.source===seed&&e.target!==seed);let sequences=[];for(const a of events){if(BigInt(a.units)===0n||a.source===a.target)continue;for(const b of events){if(a.target===b.source&&b.source!==b.target&&a.units===b.units&&order(a,b)<0){const seconds=(Date.parse(b.timestamp)-Date.parse(a.timestamp))/1000;if(seconds>=0&&seconds<=1800){sequences.push({first:a.id,second:b.id,seconds,amount:a.amount});if(sequences.length===20)break}}}if(sequences.length===20)break}return {incoming:incoming.length,outgoing:outgoing.length,in_total:amount(incoming.reduce((n,e)=>n+BigInt(e.units),0n)),out_total:amount(outgoing.reduce((n,e)=>n+BigInt(e.units),0n)),tiny:incoming.filter(e=>BigInt(e.units)>0n&&BigInt(e.units)<1000n).length,sequences}}
export function csv(events){const keys=['timestamp','block','tx','log_index','source','target','amount','units'];return [keys.join(','),...events.map(e=>keys.map(k=>'"'+String(e[k]).replaceAll('"','""')+'"').join(','))].join('\n')}
export function report(c,notes){const f=findings(c.events,c.manifest.seed);return `# Trace Desk investigation review\n\nMode: ${c.mode||'saved example'}\nSeed: ${c.manifest.seed}\nBlocks: ${c.manifest.from_block}–${c.manifest.to_block}\nProvider: ${c.manifest.endpoint}\nCaptured: ${c.manifest.captured_at}\nCoverage: ${c.coverage||'Saved two-hop neighborhood, 24-address cap.'}\n\n## Recorded activity\n${c.events.length} events. Seed incoming: ${f.incoming} (${f.in_total} USDT); outgoing: ${f.outgoing} (${f.out_total} USDT). Self-transfers excluded from directional totals. Totals describe fetched activity, not balances.\n\n## Analyst observations\n${notes.observations||'Not recorded'}\n\n## Alternative explanations\n${notes.alternatives||'Not recorded'}\n\n## Missing evidence / next steps\n${notes.next||'Not recorded'}\n\n## Review disposition\n${notes.disposition||'Unreviewed'}\n\n## Limits\nAddress does not identify a person. Relationships and same-amount sequences do not prove common ownership, illicit activity, or identical funds. No KYC, opening balances, or exchange fiat-conversion records. Provider completeness is assumed; no cryptographic inclusion proof. Failed or unqueried counterparties are not cleared.\n\n## Event register\n${csv(c.events)}\n`}
export function mergeReview(base,added){
 if(!base.queried_addresses||base.queried_addresses.length>=5)throw Error('Five-address query cap reached.');
 if(base.start!==added.start||base.end!==added.end||base.manifest.from_block!==added.manifest.from_block||base.manifest.to_block!==added.manifest.to_block)throw Error('Expansion window differs from original case.');
 const seed=added.manifest.seed;if(base.queried_addresses.includes(seed))throw Error('Address already queried.');
 if(!base.events.some(e=>e.source===seed||e.target===seed))throw Error('Expansion must be an observed counterparty.');
 const events=unique([...base.events,...added.events]);if(events.length>1000)throw Error('Combined case exceeds 1,000 events. Start a narrower review.');
 const queried=[...base.queried_addresses,seed],origin=base.manifest.seed;
 const peers=[...new Set(events.flatMap(e=>[e.source,e.target]))].filter(a=>a!==origin&&a!==ZERO).sort();
 return {...base,events,queried_addresses:queried,raw:[...base.raw,...added.raw],nodes:[{address:origin,depth:0},...peers.slice(0,24).map(a=>({address:a,depth:events.some(e=>(e.source===origin&&e.target===a)||(e.target===origin&&e.source===a))?1:2}))],omitted_addresses:peers.slice(24),window_event_count:events.length,coverage:'Incoming and outgoing USDT queried for '+queried.join(', ')+'. UTC window ['+base.start+', '+base.end+'). Other counterparties are not expanded. Graph capped at 25 addresses; all returned events retained in table and exports. Purple nodes are indirect counterparties, not a hop-count guarantee. Request records include capture times.'};
}
